PRAGMA foreign_keys = ON;
CREATE TABLE provinces (id INTEGER PRIMARY KEY, name TEXT NOT NULL, name_np TEXT);
CREATE TABLE districts (id INTEGER PRIMARY KEY, province_id INTEGER NOT NULL, name TEXT NOT NULL, name_np TEXT, FOREIGN KEY (province_id) REFERENCES provinces(id));
CREATE TABLE local_levels (id INTEGER PRIMARY KEY AUTOINCREMENT, district_id INTEGER NOT NULL, name TEXT NOT NULL, name_np TEXT, type TEXT CHECK(type IN ('Metropolitan','Sub-Metropolitan','Municipality','Rural Municipality')), wards INTEGER DEFAULT 9, FOREIGN KEY (district_id) REFERENCES districts(id));
CREATE INDEX idx_local_levels_district ON local_levels(district_id);
CREATE TABLE registration_types (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, sort_order INTEGER DEFAULT 0, active INTEGER DEFAULT 1);
CREATE TABLE business_categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, sort_order INTEGER DEFAULT 0, active INTEGER DEFAULT 1);
CREATE TABLE services (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, default_fee REAL DEFAULT 0, is_recurring INTEGER DEFAULT 0, recurrence_type TEXT, active INTEGER DEFAULT 1);
CREATE TABLE document_types (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, sort_order INTEGER DEFAULT 0, active INTEGER DEFAULT 1);
CREATE TABLE staff (id INTEGER PRIMARY KEY AUTOINCREMENT, staff_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, position TEXT, contact TEXT, email TEXT, active INTEGER DEFAULT 1, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE clients (id INTEGER PRIMARY KEY AUTOINCREMENT, client_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, pan_no TEXT, registration_type_id INTEGER, business_category_id INTEGER, category TEXT CHECK(category IN ('one_time','regular')) DEFAULT 'one_time', registration_date TEXT, authorised_person TEXT, contact_number TEXT, email TEXT, province_id INTEGER, district_id INTEGER, local_level_id INTEGER, ward_no INTEGER, address_line TEXT, remarks TEXT, active INTEGER DEFAULT 1, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (registration_type_id) REFERENCES registration_types(id), FOREIGN KEY (business_category_id) REFERENCES business_categories(id), FOREIGN KEY (province_id) REFERENCES provinces(id), FOREIGN KEY (district_id) REFERENCES districts(id), FOREIGN KEY (local_level_id) REFERENCES local_levels(id));
CREATE INDEX idx_clients_category ON clients(category);
CREATE INDEX idx_clients_district ON clients(district_id);
CREATE INDEX idx_clients_active ON clients(active);
CREATE TABLE client_documents (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER NOT NULL, document_type_id INTEGER NOT NULL, status TEXT CHECK(status IN ('yes','partial','no','na')) DEFAULT 'no', received_date TEXT, remarks TEXT, updated_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE, FOREIGN KEY (document_type_id) REFERENCES document_types(id), UNIQUE(client_id, document_type_id));
CREATE TABLE client_document_files (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER NOT NULL, document_type_id INTEGER NOT NULL, file_name TEXT NOT NULL, stored_name TEXT NOT NULL, file_path TEXT NOT NULL, file_size INTEGER, mime_type TEXT, notes TEXT, uploaded_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE, FOREIGN KEY (document_type_id) REFERENCES document_types(id));
CREATE INDEX idx_docfiles_client ON client_document_files(client_id);
CREATE TABLE client_services (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER NOT NULL, service_id INTEGER NOT NULL, estimated_fee REAL DEFAULT 0, tax_amount REAL DEFAULT 0, active INTEGER DEFAULT 1, created_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE, FOREIGN KEY (service_id) REFERENCES services(id), UNIQUE(client_id, service_id));
CREATE TABLE work_assignments (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER NOT NULL, service_id INTEGER NOT NULL, title TEXT, fiscal_year TEXT, priority TEXT CHECK(priority IN ('high','medium','low')) DEFAULT 'medium', status TEXT CHECK(status IN ('not_started','started','wip','due_today','due_soon','overdue','completed')) DEFAULT 'not_started', start_date TEXT, due_date TEXT, completed_date TEXT, estimated_hours REAL, actual_hours REAL, assigned_staff_id INTEGER, supervisor_id INTEGER, notes TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE, FOREIGN KEY (service_id) REFERENCES services(id), FOREIGN KEY (assigned_staff_id) REFERENCES staff(id), FOREIGN KEY (supervisor_id) REFERENCES staff(id));
CREATE INDEX idx_work_status ON work_assignments(status);
CREATE INDEX idx_work_due ON work_assignments(due_date);
CREATE INDEX idx_work_client ON work_assignments(client_id);
CREATE TABLE vat_tracking (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER NOT NULL, fiscal_year TEXT NOT NULL, month_index INTEGER NOT NULL CHECK(month_index BETWEEN 1 AND 12), month_name TEXT NOT NULL, status TEXT CHECK(status IN ('pending','submitted','filed','late')) DEFAULT 'pending', filed_date TEXT, assigned_staff_id INTEGER, remarks TEXT, updated_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE, FOREIGN KEY (assigned_staff_id) REFERENCES staff(id), UNIQUE(client_id, fiscal_year, month_index));
CREATE TABLE invoices (id INTEGER PRIMARY KEY AUTOINCREMENT, invoice_no TEXT NOT NULL UNIQUE, client_id INTEGER NOT NULL, service_id INTEGER, work_id INTEGER, invoice_date TEXT NOT NULL, due_date TEXT, service_fee REAL NOT NULL DEFAULT 0, tax_amount REAL DEFAULT 0, total_amount REAL NOT NULL DEFAULT 0, paid_amount REAL DEFAULT 0, status TEXT CHECK(status IN ('unpaid','partial','paid','cancelled')) DEFAULT 'unpaid', remarks TEXT, created_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (client_id) REFERENCES clients(id), FOREIGN KEY (service_id) REFERENCES services(id), FOREIGN KEY (work_id) REFERENCES work_assignments(id));
CREATE TABLE payments (id INTEGER PRIMARY KEY AUTOINCREMENT, invoice_id INTEGER NOT NULL, client_id INTEGER NOT NULL, payment_date TEXT NOT NULL, amount REAL NOT NULL, method TEXT CHECK(method IN ('cash','bank_transfer','cheque','other')) DEFAULT 'cash', bank_account TEXT, reference_no TEXT, remarks TEXT, created_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE CASCADE, FOREIGN KEY (client_id) REFERENCES clients(id));
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT, updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT, action TEXT NOT NULL, entity_type TEXT, entity_id INTEGER, details TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, message TEXT, type TEXT CHECK(type IN ('info','warning','danger','success')) DEFAULT 'info', read INTEGER DEFAULT 0, link TEXT, created_at TEXT DEFAULT (datetime('now')));
